grundstuecksaufgebot_kombinierte_zeitgrenze <- function(berechnetes_eigenbesitzfristende=NULL, letzte_massgebliche_zustimmungseintragung_am=NULL, einordnungsnachweis=NULL) {
 besitz <- .datum(berechnetes_eigenbesitzfristende,'berechnetes_eigenbesitzfristende');.text(einordnungsnachweis,'einordnungsnachweis')
 ruhe <- if(is.null(letzte_massgebliche_zustimmungseintragung_am)) NULL else .frist(letzte_massgebliche_zustimmungseintragung_am,30,'jahre','ereignis')
 wert <- list(grundbuchruhefristende=if(is.null(ruhe)) NULL else .iso(ruhe),rechnerische_kombinierte_zeitgrenze=.iso(if(is.null(ruhe)) besitz else max(besitz,ruhe)))
 eingaben <- list(berechnetes_eigenbesitzfristende=berechnetes_eigenbesitzfristende, letzte_massgebliche_zustimmungseintragung_am=letzte_massgebliche_zustimmungseintragung_am, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,"daten","BGB_GRUNDSTUECKSAUFGEBOT_KOMBINIERTE_ZEITGRENZE",eingaben,list(list(operation="30J\u00e4hrige Grundbuchruhe seit qualifizierter Zustimmungseintragung berechnen und mit bereits berechneter Besitzfrist als sp\u00e4testes Ende verkn\u00fcpfen.")),eingaben)
 ergebnis$hinweise <- list("\u00a7927I: berechnetes Ende der30j\u00e4hrigen Eigenbesitzzeit mit gegebenenfalls zus\u00e4tzlicher30j\u00e4hriger Grundbuchruhe seit letzter eigent\u00fcmerzustimmungsbed\u00fcrftiger Eintragung als sp\u00e4teste Zeitgrenze verkn\u00fcpfen. Besitzfrist zuvor einschlie\u00dflich rechtlich wirksamer Hemmung, Unterbrechung und Zurechnung berechnen; ersitzung_anrechenbare_zeitkette stellt den numerischen Kern bereit. Grundbuchruhe nicht unbesehen um die Besitzhemmung verl\u00e4ngern. Null bei Eintragung darf keine ungepr\u00fcfte oder unbekannte Historie verdecken. Ausschlie\u00dflich Zeitrechnung; kein Urteil \u00fcber Tod/Verschollenheit, Aufgebotszul\u00e4ssigkeit, Ausschlie\u00dfungsbeschluss oder Eigentumserwerb. Erf\u00fcllung erst nach vollst\u00e4ndigem Ablauf des jeweiligen Endtags; keine automatische193-Verschiebung.")
 ergebnis
}
